import torch

# Check if the input batch is a torch.Tensor or np.ndarray
if isinstance(batch, (torch.Tensor, np.ndarray)):
    # If it's already a tensor or array, add a new dimension at the zeroth position using torch.unsqueeze
    return torch.unsqueeze(batch, 0)

# Check if the input batch is a tuple or list
elif isinstance(batch, (tuple, list)):
    # Recursively apply add_batch to each element in the tuple or list
    # and then stack the results using torch.stack
    return torch.stack([add_batch(item) for item in batch]).unsqueeze(0)

# Check if the input batch is a dictionary
elif isinstance(batch, dict):
    # Recursively apply add_batch to each value in the dictionary
    # and then stack the results using torch.stack
    return torch.stack([add_batch(value) for value in batch.values()]).unsqueeze(0)

# If the input batch is not a supported type, raise a ValueError
else:
    raise ValueError("Unsupported input type. Please use a torch.Tensor, np.ndarray, tuple, list, or dict.")

